import json, hashlib
from pathlib import Path
import ida_bytes, ida_funcs, ida_name, ida_ua, idautils, idc
outdir=Path('C:/Dev/Astra_A2WC511R/reports/local/ida')
rom=ida_bytes.get_bytes(0,0x100000)
def lines(start,end):
    out=[]
    for ea in range(start,end,2):
        insn=ida_ua.insn_t();size=ida_ua.decode_insn(insn,ea)
        out.append({'ea':hex(ea),'bytes':rom[ea:ea+2].hex(),'persistent_code':ida_bytes.is_code(ida_bytes.get_flags(ea)),
            'text':idc.generate_disasm_line(ea,idc.GENDSM_FORCE_CODE) if size else None})
    return out
out={'sha256':hashlib.sha256(rom).hexdigest(),'windows':{},'literal_candidates':[],'special_instructions':[],
     'ram_names':[],'function_count':sum(1 for _ in idautils.Functions(0,0x100000))}
for a,b in [(0x118B0,0x11980),(0x11AC0,0x11B00),(0x11200,0x11258),(0xD1A0,0xD270),
            (0xF9BC,0xFB20),(0x660,0x740),(0x11900,0x11A00)]:
    out['windows'][hex(a)]=lines(a,b)
for ea in range(0,0x100000-3,2):
    val=int.from_bytes(rom[ea:ea+4],'big')
    if 0xffff7000<=val<0xffff8000 or 0xe0000<=val<0xe4000:
        out['literal_candidates'].append({'ea':hex(ea),'value':hex(val),'aligned4':ea%4==0,
           'xrefs':[{'from':hex(x.frm),'type':x.type,'code':bool(x.iscode)} for x in idautils.XrefsTo(ea)]})
for ea in idautils.Heads(0,0x859bc):
    if not ida_bytes.is_code(ida_bytes.get_flags(ea)):continue
    text=idc.generate_disasm_line(ea,0) or ''
    if any(k in text.lower() for k in ['vbr','gbr','r15','ecc','ed0','ed1']):
        out['special_instructions'].append({'ea':hex(ea),'text':text})
for ea,name in idautils.Names():
    if 0xffff6800<=ea<0xffff8000:
        out['ram_names'].append({'ea':hex(ea),'name':name,'xrefs':[{'from':hex(x.frm),'type':x.type} for x in idautils.XrefsTo(ea)]})
(outdir/'allocation_static_audit.json').write_text(json.dumps(out,indent=2),encoding='utf-8')
print(json.dumps({'functions':out['function_count'],'literal_candidates':len(out['literal_candidates']),
 'named_ram':len(out['ram_names']),'special_instructions':len(out['special_instructions'])}))
